import{_ as o,o as t,c as p,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"2019-01-02 :: Ceph Developer Monthly","description":"","frontmatter":{"title":"2019-01-02 :: Ceph Developer Monthly","date":"2019-01-02T00:00:00.000Z","updated":"2019-01-04T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","可伸缩性","对象存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-01-02_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2019/2019-01-02_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780460162000}'),r={name:"posts/2019/2019-01-02_-_-_Ceph_Developer_Monthly.md"};function _(s,e,i,n,a,h){return t(),p("div",null,[...e[0]||(e[0]=[l("<p>本次Ceph开发者月度会议于2023年5月19日举行，主要讨论了以下议题：</p><ol><li><p><strong>新Monitor添加问题</strong>：David指出在添加新Monitor时，需要指定公共地址，但当前无法指定。会议决定通过Orchestrator命令要求指定公共网络，并在CLI中实现该功能。</p></li><li><p><strong>Ceph应用功能需求</strong>：讨论了Ceph应用在RadosOS上构建的一些功能需求，包括自定义操作、可扩展性解决方案以及元数据管理。</p></li><li><p><strong>Skyhook应用功能需求</strong>：讨论了Skyhook应用在Ceph存储上的一些功能需求，包括集合级别锁定和元数据管理。</p></li><li><p><strong>多对象操作</strong>：讨论了在Ceph中实现多对象操作的需求，包括PG级别操作和原子性。</p></li><li><p><strong>返回数据</strong>：讨论了在对象操作中返回数据的可行性，包括返回数据大小和用途。</p></li></ol><p>会议决定后续行动计划如下：</p><ul><li>David将研究如何通过Orchestrator命令指定公共网络。</li><li>Jeff和Southern Cal将研究如何实现自定义操作和可扩展性解决方案。</li><li>Brad将研究如何在Skyhook中实现集合级别锁定和元数据管理。</li><li>全体参与者将继续讨论多对象操作和返回数据的需求。</li></ul><p>会议中提到的Ceph组件包括Monitor、OSD、PG、Rados、CLI等，使用了Ceph术语，例如原子性、可扩展性、元数据、集合级别锁定等。</p>",5)])])}const c=o(r,[["render",_]]);export{C as __pageData,c as default};
